// Stage stories with dates
export const STAGE_STORIES = {
  // Chapter 1: Arrival in Linnaria
  1: { date: "Mar 18, 2157", dateZh: "2157年3月18日", story: "Since the sky-ship made landfall three months ago, Lily had not truly looked at this city that once existed only in fantasy. In the shelter, days were spent in orientation—learning the basics of this new world, and searching limited records for traces of her friends. The instructor explained that due to current technology's inability to calibrate worldline currents, she and her companions were sent to different spacetimes. 'Please be patient, we are working on it,' they said. But patience was a luxury for those who had not watched their world burn. Through the shelter's narrow windows, Lily glimpsed towers of glass and light, a metropolis built upon the ashes of everything she had lost. Her grandfather's compass weighed heavy in her pocket—a relic of a past that no longer existed in any timeline she could reach.", storyZh: "自从三个月前天空船登陆以来，莉莉还没有真正地看过这座曾经仅存在于幻想作品中的都市。在庇护所里的日子，她接受了新世界基础知识的培训，同时在有限的信息中寻找着朋友们的踪迹。培训员解释说，由于当前技术无法校准世界线流向，她和朋友们的灵魂被送到了不同的时空中。'请耐心等待，我们正在研究，'他们说道。但耐心是那些没有目睹过自己世界燃烧的人才能享受的奢侈品。透过庇护所狭窄的窗户，莉莉瞥见了玻璃和光构成的高塔——一座建立在她失去的一切灰烬之上的大都会。祖父的指南针在她口袋里沉甸甸的——那是一段在任何时间线都无法触及的过去的遗物。" },
  2: { date: "Mar 18, 2157", dateZh: "2157年3月18日", story: "Crossing the Bridge of Origin into the city proper. From the north side of the bridge, the twin Gothic spires support a glass greenhouse shaped like a double disc, connected by skywalks. The white halo around them forms the symbol of infinity. Lily pressed the button on her cognition glasses, and the symbol '\u221e' was collected into her stamp book. But beneath the bridge, drawn by her temporal displacement, something stirred.", storyZh: "穿过原点之桥走向城市。在桥的北侧步道正中心望去，双圆盘形的玻璃温室被两座哥特式尖塔支撑着，与周围的玻璃栈道相连。纯白的光环形成了一个'无限'的符号——这是琳娜利亚的标志，代表着时间与空间的无限循环。莉莉按下智识眼镜上方的按钮，符号被收录在了集章册里。她感到一阵眩晕，仿佛这个符号在回应着她体内残留的时空能量。在桥下，有什么东西骚动了起来——被她的时空位移吸引，无数历史残影在桥墩的阴影中若隐若现。" },
  3: { date: "Mar 20, 2157", dateZh: "2157年3月20日", story: "The windmill coast stretched before her — warm-colored sails spinning above fields of flowers. Tour boats drifted downstream carrying musicians playing something ancient yet indescribable. Beyond lay a Renaissance palace ringed by towering old-growth trees, and a harbor market half-veiled in sea fog. Every corner was new, yet the weight of history was undeniably real. Linnaria — reborn so many times it induced vertigo in a traveler from a thousand years past.", storyZh: "风车花海展开在她面前——暖色的风车在花田上旋转，仿佛永不停歇的舞蹈。游船顺流而下，船上的演奏者带来了像是古代民族乐但又无法描述的音乐，每一个音符都蕴含着某种难以名状的乡愁。远处是一座被参天古木环绕的复兴式宫殿，殿宇的轮廓在晨雾中若隐若现，透露出威严与神秘。还有在海雾中隐现的港口集市，商贩的叫卖声与海鸥的鸣叫交织成一首独特的城市交响曲。这里的每一处都是崭新的，哪怕历史的厚重也是实实在在的——每一块石砖都承载着被遗忘的故事。琳娜利亚，这座经历了数次洗礼和重生的城市，以足以让千年前的旅人产生眩晕的姿态展现在眼前。" },
  4: { date: "Apr 2, 2157", dateZh: "2157年4月2日", story: "The tunnel through the Tiandu Mountains. Inside the cylindrical glass skyway, thick snow pressed against the exterior like a beast baring its fangs. In the maintenance corridors below the tracks, something from the centuries of war still lingered: soldiers who never received orders to stand down.", storyZh: "穿过天都山脉的隧道。圆柱形玻璃栈道内部，厚重的积雪紧贴着外壁，从内部看上去就像一只露出两颗虎牙试图吞没一切历史的巨兽，正虎视眈眈地注视着每一个过客。在轨道下方的维护通道中，数百年战争的某些东西仍在徘徊——那些从未收到撤退命令的士兵。他们的身影在应急灯的闪烁中若隐若现，空洞的眼神诉说着永恒的困惑与不甘。指南针在莉莉的口袋中微微发热，提醒着她这些残留的力量正在被她的时空能量所吸引。" },
  5: { date: "Apr 3, 2157", dateZh: "2157年4月3日", story: "Emerging into Tiandu City. Compared to Linnaria's extreme colors, Tiandu in deep winter had only black, white, and grey. Lily followed signs through large residential districts and underground shopping levels. In forgotten maintenance corridors between the glass skyways, stronger remnants patrolled.", storyZh: "走出地铁站，进入天都城。相比琳娜利亚的极彩色，仍处于真冬的天都城只有黑白灰的色调，整座城市仿佛一幅泼墨山水画，简洁而肃穆。莉莉循着指示牌穿过大型居民区和商场的地下层，橱窗里的全息广告闪烁着未来的承诺，却无法驱散空气中弥漫的寒意。在玻璃栈道间被遗忘的维护通道中，更强的残留体在巡逻——它们是这座城市过去的守护者，如今却成了时间的囚徒，无望地等待着永远不会到来的黎明。" },
  6: { date: "Apr 4, 2157", dateZh: "2157年4月4日", story: "Beneath the Chronology Museum, built on the ruins of the original Lyra Palace. The museum's exterior was a vast neo-Gothic cathedral, far larger than the Lyra Palace described in Lily's journal. White flying buttresses and spires pierced the clouds. But beneath it, the old foundations still pulsed.", storyZh: "编年史博物馆的地下，建立在天琴宫原址之上。这座建筑的设计者似乎在刻意模仿某种古老的辉煌，博物馆的外形是一座巨大的仿古式教堂，比莉莉日记本里描述的天琴宫还要大得多。纯白的飞扶壁和哥特式尖塔直插云腹，昭示着人类对永恒的追求。但在它下方，古老的地基仍在脉动——那是星凝教三千年信仰凝聚的力量，穿越时空的屏障，呼唤着它最后的继承者。莉莉感到心跳加速，她知道自己已经接近了某个重要秘密的边缘。" },
  7: { date: "Apr 4, 2157", dateZh: "2157年4月4日", story: "Deeper in the museum's lower levels. The glowing projection globes displayed any region in any year with a touch. Concentrated temporal energy attracted entities that fed on the residue of history. The religious war from 1179 to 1492 had left the deepest scars.", storyZh: "博物馆更深处。发光的地球仪只需动动手指就能在投影中还原某个地区某一年的景象，历史的每一个瞬间都触手可及。然而，凝聚的时空能量也吸引了以历史残余为食的实体——它们贪婪地吞噬着过去的回声，壮大着自己的力量。1179年到1492年的宗教战争留下了最深的伤痕，无数灵魂在这场信仰的战争中消亡，他们的怨恨至今仍在空气中徘徊。莉莉意识到，这座博物馆不仅是历史的记录者，也是历史伤口的守护者——它保存着伤痛，却也在治愈着伤痛。" },
  8: { date: "Apr 4, 2157", dateZh: "2157年4月4日", story: "A projection of the fall of Victoria materialized. Eternal Slumber soldiers stepped out of the historical record itself, still burning with the fervor of holy war. Their ash-grey robes bore the inverted crescent. The nearly three centuries of genocide had left echoes so dense they could take physical form.", storyZh: "维克多利亚陷落的投影化为了实体。永眠教的士兵从历史记录中走出，仍燃烧着圣战的狂热，每一个动作都带着三百年前那场浩劫的余温。他们灰色的长袍上印着倒新月的标志——那是对星凝教信仰的亵渎与扭曲。莉莉看到投影中城市的街道被火焰吞噬，无辜者的哭喊声与士兵的欢呼声交织成一曲地狱般的合唱，近三百年的屠杀留下了如此浓密的回声，足以化为实体。这些残留不是普通的幽灵，而是被仇恨浸透的历史碎片，永远在重复着那段不可原谅的过去。" },
  9: { date: "Apr 4, 2157", dateZh: "2157年4月4日", story: "The full weight of three centuries of religious war concentrated into this space. Slumber Preachers chanted their doctrine of eternal death while Void Acolytes drained the light from the projection hall. The entire northwest continent had been nearly exterminated; only a few hundred survivors on a small island escaped behind walls of magic ice.", storyZh: "三百年宗教战争的全部重量凝聚在这个空间中。永眠教的传道者吟唱着永恒死亡的教义，他们的声音如同毒液，缓缓侵蚀着空气中残存的希望。虚空侍僧从投影厅中抽取光芒，将一切美好化为虚无——他们的黑袍上绣满了倒新月，那是星神陨落的象征。整个西北大陆几乎被屠戮殆尽，无数城市化为废墟，曾经繁荣的文明只剩下断壁残垣。只有里格尔岛上寥寥数百人逃过一劫，躲在魔法凝成的冰墙之后，在绝望中等待着救赎的来临。莉莉终于明白了——祖父日记中提到的'那场战争'，远比她想象的更加惨烈。" },
  10: { date: "Apr 4, 2157", dateZh: "2157年4月4日", story: "At the deepest point of the museum's foundations, where Lyra Palace's altar once stood, a fragmented avatar of Thanatos coalesced from centuries of concentrated fanaticism. Not a true god, but the crystallized hatred of an entire era given form. Lily's grandfather's compass burned hot in her pocket. He had been here before.", storyZh: "在博物馆地基的最深处，天琴宫祭坛曾经矗立的地方，塔纳托斯的碎片化身从数百年凝聚的狂热中凝结而出。这并非真正的神灵，而是一整个时代结晶化的仇恨被赋予了形体，它的存在本身就是对那场宗教战争的控诉。莉莉口袋里祖父的指南针突然灼热起来，指针疯狂地旋转，仿佛在警告什么。祖父曾经来过这里——她突然意识到，那本烧毁了一半的日记里，为何会有这座博物馆的素描。" },

  // Chapter 2: Ruined Kingdom
  11: { date: "Apr 13, 2157", dateZh: "2157年4月13日", story: "The ferry from White Heron Port cut through the narrow Cape of Sunken Ships, heading north before turning west at Sunset Pier's orange rooftops. When the sea fog thickened enough to swallow the horizon, the ancient church spire of Rigel Island emerged. Researcher Séraphine and her two students observed from the jungle behind the coast as Lily prepared the first ritual.", storyZh: "从白鹭港出发的渡船穿过狭窄的沉船海峡一路向北，然后在夕日码头的橙红色屋顶前转向西行。浓密的海雾几乎要吞没整个地平线时，里格尔岛那座古老教堂的尖顶终于从迷雾中浮现。研究员塞拉芬和她两名学生从海岸后方的丛林中观察着莉莉准备第一次仪式。里格尔——一座被世人遗忘的岛屿，却曾是星凝教最神圣的朝圣地。三百年前的战火中，它是如何幸存的？莉莉握紧手中的指南针，金属的冰凉与她内心的温热形成鲜明对比。她能感觉到，这座岛屿承载着她祖父留下的某些秘密。" },
  12: { date: "Apr 13, 2157", dateZh: "2157年4月13日", story: "On the moonlit shore, Lily stood between the geometric monuments and archways left by ancient pilgrims. She draped the blue-and-white scarf across her back, held up the star-dust crystal, and scattered moonlight into the sky. 'Star God, please guide me toward Linnaria...' The eastern stars flickered for an instant. But the energy from afar was too faint. Something in the island's old ruins resisted the connection.", storyZh: "月光洒落在海岸上，莉莉站在古老朝圣者留下的几何石碑和拱门之间。她将蓝白相间的围巾披在背上，举起星尘水晶，将月光洒向天空。'星神啊，请指引我前往琳娜利亚……'东方的星辰闪烁了一瞬，但随即暗淡下去。远处传来的能量太过微弱，岛屿古老废墟中的某些东西抗拒着这次连接。莉莉感到一阵眩晕——她看到石碑上刻着的文字与祖父日记中的符号惊人地相似，仿佛有某种跨越时空的联系正在形成，却被什么力量阻挡着。" },
  // Chapter 2: Rigel Island
  13: { date: "Apr 14, 2157", dateZh: "2157年4月14日", story: "The ancient temple ruins. Columns of white marble, weathered by three centuries of salt wind. Lily walked where pilgrims once tread, seeking visions of the Star God. Among the fallen stones, she found carvings of constellations her grandfather had drawn in his journal.", storyZh: "古老的神殿废墟矗立在眼前，白色大理石的廊柱被三个世纪的海风侵蚀得斑驳不堪。莉莉走在朝圣者们曾经踏过的石板上，寻求星神的异象。在倒塌的石块间，她发现了祖父曾在日记中绘制的星象雕刻——同样的符号，同样的排列，仿佛跨越时空的呼应。里格尔岛的神殿曾是星凝教最神圣的所在，三百年的战火未能将其彻底摧毁，只留下这些残垣断壁在海风中诉说着曾经的辉煌。" },
  14: { date: "Apr 15, 2157", dateZh: "2157年4月15日", story: "The instrument shop. Ancient lutes and harps lined dusty shelves. 'This lyre,' Séraphine said, 'was played during the last ritual on this island. The musician's name was... I cannot remember.' The strings hummed without being touched.", storyZh: "乐器修理店内，古老的长颈琴和竖琴排列在落满灰尘的架子上。'这把鸢尾琴，'塞拉芬说道，'曾在岛上最后一次仪式中演奏。演奏者的名字是……我想不起来了。'奇怪的是，琴弦在没有被人触碰的情况下自行发出低沉的嗡鸣。莉莉走近细看，发现琴身上刻着与祖父日记中相同的符文——那是一种只有星凝教核心成员才能解读的古老文字。这把琴为何会出现在这里？它与三百年前的仪式有何关联？" },
  15: { date: "Apr 16, 2157", dateZh: "2157年4月16日", story: "A cabin on the western shore. Through salt-crusted windows, Lily watched the sun sink into the sea. The lighthouse beam swept past every eight seconds. 'My grandfather lived here,' she whispered, recognizing the sketches in his journal.", storyZh: "西海岸的小木屋。透过结满盐霜的窗户，莉莉注视着太阳沉入大海。灯塔的光束每八秒扫过一次，将海面照得通明。'祖父曾住在这里，'她低语道，因为她认出了日记中的素描——同样的窗户、同样的位置、同样的灯塔光影。屋内的一切都已蒙尘，但角落里放着一本笔记，翻开一看，竟是祖父的字迹。他在这座岛上生活过、研究过，记录着星凝教的秘密与仪式的关键。祖父究竟发现了什么，让他不得不离开这座岛？" },
  16: { date: "Apr 17, 2157", dateZh: "2157年4月17日", story: "Midnight on the beach. Séraphine drew symbols in the sand—ancient protection wards. 'The ritual failed before,' she warned. 'Something in the island resists connection to the Star God.' Lily felt the compass pulse with each wave.", storyZh: "午夜的海滩。塞拉芬在沙中画出符号——古老的防护结界。'之前的仪式都失败了，'她警告道，'岛上有某种力量在抗拒与星神的连接。'莉莉感到指南针随着每一道海浪的拍打而脉动，仿佛在回应着这片土地深藏的秘密。海风带来低沉的吟唱声，是三百年前信徒们祈祷的回响，还是某种不愿被遗忘的存在在试图传递讯息？塞拉芬的脸色凝重，她知道一些不愿说出的真相——这座岛不仅庇护着星凝教的遗产，也封印着某段不应被唤醒的记忆。" },
  17: { date: "Apr 18, 2157", dateZh: "2157年4月18日", story: "The Tiandu Mountains loomed inland. Séraphine led them through passes where snow never melted, where wind carried whispers of ancient prayers. 'The Star God spoke here once,' she said. 'Now the mountains only echo emptiness.'", storyZh: "天都山脉在内陆若隐若现。塞拉芬带领他们穿过常年积雪不化的山口，那里的大风携带着古老祈祷的低语。'星神曾在这里说话，'她说道，'但现在山脉只回响着空虚。'莉莉感到指南针的指针在剧烈颤抖，仿佛在寻找某个早已消失的声音。山路两旁矗立着被风雪侵蚀的石碑，上面刻满了星凝教的经文，但字迹已经模糊得难以辨认。三百年的时光将这些神圣的印记磨灭得几乎不留痕迹，只剩下呼啸的山风在诉说着那段被遗忘的历史。" },
  18: { date: "Apr 19, 2157", dateZh: "2157年4月19日", story: "An octagonal temple at the mountain's heart. Eight doors, eight prayers, eight names of the Star God. Inside, a mirror that reflected not their faces but their memories—faces of the dead, places that no longer existed.", storyZh: "位于山心的八角形神殿。八扇门、八首祈祷文、八位星神的名号。殿内有一面镜子，映照的不是他们的面容，而是他们的记忆——逝者的面容、已不存在的场所。莉莉在镜中看到了祖母的脸庞，看到了故乡燃烧的村庄，看到了那场将她抛入未来的灾难性战争。这面镜子能够捕捉时间线中残留的影像，将过去、现在与可能的未来交织在一起。塞拉芬低声说道：'这就是为什么我们必须成功——为了让这些记忆不再只是回响，而是成为可以触及的现实。'" },
  19: { date: "Apr 20, 2157", dateZh: "2157年4月20日", story: "Traveler Fruits—trees that bloomed only once per century. Séraphine picked three, one for each timeline. 'Eat this, and you'll remember what you lost. But the cost... the cost is remembering why you lost it.'", storyZh: "旅人之果——每百年才开一次花的果树。塞拉芬摘了三颗，每个时间线一颗。'吃下它，你会记起你失去的一切。但代价是……代价是记起你为何失去它。'莉莉握着那颗果实，感受着它在掌心的温热。这是岛上的神圣馈赠，也是残酷的试炼——忘记痛苦是慈悲，记住痛苦是责任。当她咬下第一口时，无数画面涌入脑海：母亲在战火中的呼喊、朋友们在逃亡时的面孔、故乡沦陷时天空的颜色。她终于明白，遗忘不是解脱，记忆才是真正的力量。" },
  20: { date: "Apr 21, 2157", dateZh: "2157年4月21日", story: "Tír na nÓg—the realm beyond the veil. Where the Star God's children played instruments made of light. 'Grandfather,' Lily whispered. 'You came here. You found the origin of the symphony.' The music had always been calling her home.", storyZh: "常春之地——帷幕彼端的领域。星神的孩子们在这里演奏着用光铸成的乐器。'祖父，'莉莉低语道，'您来过这里。您找到了乐章的源头。'音乐一直在呼唤她回家。常春之地不是死亡后的世界，而是信仰汇聚之处——每一个仰望星空许下愿望的灵魂，都在这里留下了共鸣的回声。祖父曾追寻这个答案，现在莉莉站在了他曾经站立的地方，感受着同样的震撼与敬畏。她终于明白，星凝教的真正教义不是崇拜某个具体的神明，而是相信人类的声音能够穿越虚空，与宇宙产生共鸣。" },

  // Chapter 3: World Tree Journey
  21: { date: "Aug 12, 2157", dateZh: "2157年8月12日", story: "Return to Rigel Island. 'Solros transformed into stardust on June 2nd,' reads the notice. Her granddaughter Agnès waits at the western shore cabin, ready to reveal the last viewing crystal.", storyZh: "再次来到里格尔岛。乐器店的门上贴着一张告示：'索尔诺斯女士已于6月2日化为星辰。'莉莉和塞拉芬来到西海岸的小木屋，索尔诺斯的孙女艾格西斯正在那里等候。'在她离去之前，她让我把这个给您看——最后一次寻星仪式的水晶影像。'艾格西斯从柜子里取出水晶，当画面投射出来时，莉莉看到了一个多世纪前的仪式场景——那时的天琴宫仍然辉煌，信徒们在月下演奏群星的乐章。艾格西斯说：'星神最后的告诫是——信仰崩塌后，只有一个世界会幸存。我们必须打破这个循环。'" },
  22: { date: "Aug 19, 2157", dateZh: "2157年8月19日", story: "Deep within the World Tree's roots. Agnès leads them through passages no living person has walked in centuries. 'The tree remembers everything,' she whispers. 'Every prayer, every sacrifice, every hope.'", storyZh: "在世界树错综复杂的根系深处，艾格西斯带领着莉莉和塞拉芬穿行于几个世纪以来无人踏足的通道。墙壁上覆盖着发光的苔藓，散发出幽蓝的微光，照亮着古老的象形文字。这些文字记载着星凝教最隐秘的历史——那些被官方记录抹去的祈祷、被时间遗忘的牺牲、以及无数信徒心中永不熄灭的希望。艾格西斯的手指轻轻抚过石壁上的符文：'这棵树记得一切。'她的声音在空旷的通道中回响，'每一次祈祷、每一次牺牲、每一个愿望。它是三千年信仰的储藏室。'莉莉感到指南针在口袋中微微发热，仿佛在回应着这些古老文字中蕴含的力量。当她们深入根系时，空气变得愈发沉重，充满了某种难以名状的期待感——仿佛这棵树本身正在等待着某个特定的人、某件特定的事，来完成它守护了千年的使命。" },
  23: { date: "Aug 24, 2157", dateZh: "2157年8月24日", story: "The traveler fruits. Each bite reveals memories—Lily sees her mother's face, hears Estelle's violin, feels the warmth of home before the war. 'Eat this, and you'll remember what you lost.' The cost is remembering why.", storyZh: "在世界树之根的深处，她们找到了传说中的旅人之果。莉莉摘下一颗蓝色的果实，当汁液流入口中时，无数的画面涌入脑海——母亲在灯塔中等待的面容、埃斯黛尔的小提琴旋律、战火焚烧前的故乡全景。这些记忆如此清晰，仿佛昨天才发生。但同时她也看到了战争的残酷、朋友的离散、永恒的分离。'吃下它，你会记起你失去的一切。'艾格西斯曾这样警告。'但代价是……'代价是记起为什么失去它们。痛苦与美好同时涌入，让莉莉几乎无法承受。" },
  24: { date: "Aug 26, 2157", dateZh: "2157年8月26日", story: "Tír na nÓg—the realm where time stands still. In the eternal green fields, Lily plays the Léïger Lyre with Nightingale and Skylark. The Star God finally speaks—not in words, but in harmony.", storyZh: "穿过世界树错综复杂的根系，她们来到了常春之地——一个时间静止的永恒领域。在这里，星弦的能量凝固成可见的光芒，精灵们在枝叶间低语。当莉莉拨动里格尔鸢尾琴的琴弦时，夜莺和云雀也加入进来——她们用中提琴和铃鼓伴奏。三种乐器的旋律交织在一起，形成了前所未有的和声。就在这一刻，星神终于回应了——不是用语言，而是通过音乐的和谐。三百年的沉默终于被打破，莉莉感到一股温暖的力量涌入体内，那是来自无数信徒祈祷积累的能量。" },
  25: { date: "Sep 10, 2157", dateZh: "2157年9月10日", story: "'The merger will happen,' Séraphine reveals. 'Three worlds will become one.' Lily watches reality bend in the projection. 'We were never saving anything,' Nightingale whispers. 'We were choosing which world dies.'", storyZh: "回到基地营地后，塞拉芬向莉莉揭露了真相。'合并将会发生。'她站在控制台前，屏幕上显示着三条交织的时间线。'三个世界将合为一体。我们正在校准汇聚点。'莉莉看着投影中扭曲的现实感到一阵寒意——两座城市在远方重叠、融合的景象让她想起了世界树神庙中的预言。代号'夜莺'的研究员走到莉莉身边，用只有她能听到的声音说道：'我们从来不是在拯救什么。我们是在选择哪个世界死去。'那一刻，莉莉明白了自己肩负的使命——不是见证历史，而是试图改变它。" },
  26: { date: "Sep 15, 2157", dateZh: "2157年9月15日", story: "Five days before the merger. Séraphine plants surveillance units and arranges for Lily's capture. 'We need her energy for the calibration.' The students continue sending data, unaware of their fate.", storyZh: "合并前五天。塞拉芬在基地偷偷安装了监控装置，并安排人员在合并时控制莉莉。'我们需要她的能量来完成校准。'她对上级汇报。与此同时，云雀和夜莺仍在按时向学院发送珍贵的研究数据，她们不知道自己正在建造一个将摧毁自己世界的武器。莉莉在常春之地的经历让她更加坚定了决心——她必须找到朋友们，必须完成乐章，必须阻止这场注定失败的合并。但时间已经所剩无几，而敌人就在身边。" },
  27: { date: "Sep 20, 2157", dateZh: "2157年9月20日", story: "The students discover the truth—'The calibration data only accounts for one world, not three!' Séraphine reveals: one world survives, the other two are sacrificed for calibration.", storyZh: "真相终于浮出水面。云雀在最后一次数据分析中发现了一个致命的问题——'校准数据只计算了一个世界！根本不够容纳三个！'她紧急联系学院总部，却发现通讯已经中断。夜莺也在档案中发现了一些被加密的页面：合并参数只能容纳一个世界时，另外两个世界将被无情地抹去。塞拉芬终于坦白：伊琳学院的真正计划是——牺牲两条世界线，让一条世界线存活。'这就是为什么我们需要莉莉的能量，'她说，'她是唯一能在这场浩劫中存活的人——作为新世界的火种。'" },
  28: { date: "Nov 4, 2160", dateZh: "2160年11月4日", story: "Three years later. November 4th, 13:42. The meteor strikes—not from space, but from a collapsing timeline. The sky tears open and burns. Star God's final judgment descends, not in mercy, but in mathematics.", storyZh: "三年后的11月4日，下午1点42分。这个时间将永远铭刻在所有幸存者的记忆中。莉莉站在拘留室的窗前，突然感到一阵剧烈的眩晕——仿佛整个世界都在同一瞬间开始颤抖。然后她看到了：天空撕裂了。不是渐渐裂开，而是如同被某种无形的力量猛然撕开的幕布，露出其后燃烧的虚空。陨星从那道裂缝中坠落——不是来自太空的普通陨石，而是来自一条正在崩塌的时间线，是那条时间线所有痛苦与毁灭的具象化。它带着三个世界的怨恨、无数消亡生命的哀嚎、以及被遗忘者的最后呐喊，以超越光速的速度冲向地面。火焰从天而降，吞噬着所接触的一切——建筑、植物、人、记忆、历史。整座城市在瞬间化为炼狱，尖叫声与爆炸声交织成一曲末日的交响。星神最后的审判降临了。但这不是慈悲，不是宽恕，不是救赎——这是数学。" },
  29: { date: "Nov 4, 2160", dateZh: "2160年11月4日", story: "Warm water embraces her—the merged world dissolving back into light. The sea of light washes eastward, carrying fragments of three civilizations. Lily swims toward the only constant she can sense: Victoria's music.", storyZh: "当莉莉再次睁开眼睛时，她发现自己漂浮在一片温暖的海水之中。这是光之海——合并后的世界正在溶解回它最初的光芒。周围的一切都在缓缓分解：建筑物的轮廓如同融化的蜡烛般模糊，人们的身影在光芒中化为闪烁的碎片。光之海向东冲刷，携带着三个文明的碎片。莉莉在光之海中奋力游动，朝着她唯一能感知到的方向——维克多利亚的音乐。那旋律如同灯塔的光芒，在无尽的黑暗中为她指引方向。泪水与光之海融为一体，但只要那音乐还在，希望就不会消失。" },
  30: { date: "Nov 11, 2160", dateZh: "2160年11月11日", story: "Seven days later. The instrument shop survived. 'Vivian!' A girl with ink-stained fingers looks up from sheet music. Rain-lily petals fall outside the window. She doesn't remember the sky-ship, but she hums the symphony anyway.", storyZh: "七天后，光之海终于退去。莉莉站在一片陌生的废墟之中，世界已经面目全非。但就在她几乎要绝望的时候，她看到了那座建筑——乐器修理店奇迹般地幸存了下来。莉莉踉跄着冲进去，店内陈设依旧，熟悉得令人心碎。然后她看到了她：一个手指沾满墨水的女孩正从乐谱中抬起头来。'薇薇安妮！'莉莉脱口而出。女孩困惑地看着她——她不记得什么天空船，不记得什么合并。但当莉莉提到那首乐章时，女孩的眼中闪过一丝光芒。她张开嘴，轻轻哼唱起那段熟悉的旋律——它已深深烙印在她的灵魂之中。" },

  // Stage 31-40: Journey to Alteria
  31: { date: "Nov 6, 2157", dateZh: "2157年11月6日", story: "At the riverside café, Vivian tells her story: three years alone, the shop, adapting to a world that regressed two centuries in a day. 'Everyone forgot the old world except me. I thought I was going mad.'", storyZh: "在河畔咖啡馆，薇薇安妮向莉莉讲述了她的故事：独自在这个陌生的世界里生活了三年，守护着那间乐器修理店，适应着一个在一天之内倒退了两个世纪的世界。'除了我，所有人都忘记了旧世界。'她说道，声音中带着一丝颤抖，'每当我想起合并前的一切，身边的人却只当我是在讲述虚构的故事。我开始怀疑自己是不是真的要疯了——或许这一切只是我的幻觉？'薇薇安妮的眼眶泛红，但她很快又强撑出一个笑容，那是一种在绝望中学会的坚强。" },

  32: { date: "Nov 6, 2157", dateZh: "2157年11月6日", story: "The Léïger Lyre—23 strings, made from a tree in Tír na nÓg. Stardust clings to its frame like morning dew. 'Someone carried this through,' Vivian says. 'It was in my shop when I woke up.'", storyZh: "里格尔鸢尾琴——二十三根琴弦，由常春之地的神圣树木制作而成。这把琴的来历仿佛被笼罩在迷雾之中，琴身上附着着点点星屑，在光线下闪烁着如同晨露般的微光。薇薇安妮轻轻抚摸着琴身，眉头紧锁：'有人带着它穿越了时间。'她说道，'当我从合并的混沌中醒来时，它就在我的店里——没有留下任何关于它如何到达这里的线索。这把琴似乎在等待着什么，等待着某个人来将它唤醒。'莉莉伸出手指轻触琴弦，一段模糊的旋律在她脑海中响起，那是来自另一个世界的回响。" },

  33: { date: "Nov 7, 2157", dateZh: "2157年11月7日", story: "Flight to Alteria. Over wine country, the Lisard Sea, the desert kingdom. Below, a thousand-kilometer ring of civilization around a central lake. 'Welcome to New Victoria,' the pilot says. 'Founded 2157, population three million.'", storyZh: "飞往阿里托利亚的途中，莉莉和薇薇安妮从舷窗俯瞰着这片陌生而广袤的大地。下方是葡萄酒产区连绵的绿色丘陵，随后是碧蓝如镜的利萨德海，接着是一片金黄色的沙漠王国——那是曾经不存在于任何地图上的土地。飞机缓缓下降时，她们看到了中央湖泊周围延伸的千里环带文明，高楼林立的城市如同星辰般散落在湖畔。'欢迎来到新维克多利亚。'飞行员的声音从广播中传来，'2157年建城，人口三百万。'一座在废墟上建立的新城市，融合了三条时间线的遗产，承载着无数幸存者的希望与梦想。" },

  34: { date: "Nov 8, 2157", dateZh: "2157年11月8日", story: "New Capital Academy. Lily and Vivian join the Sphera research team—ancient communication devices that require the convergence of faith to function. 'We're trying to contact other survivors,' the lead researcher explains.", storyZh: "新都城学院的大门向她们敞开。莉莉和薇薇安妮加入了天球仪研究团队——这是一种需要汇聚信仰之力才能运作的古老通讯设备。学院的走廊里回荡着研究员们的脚步声和低声讨论，每个人脸上都带着相似的疲惫与希望交织的神情。首席研究员向她们解释道：'我们正在尝试联系其他幸存者。'他指向大厅中央那颗悬浮的巨大球体，'这些天球仪能够穿越时间的屏障，将信息传递到其他时间线。但前提是——必须有人真心相信它们能够工作。'莉莉凝视着那颗微微发光的球体，她感到自己胸中的某种力量正在与之共鸣，那是来自星凝教信仰的遗产。" },

  35: { date: "Nov 9, 2157", dateZh: "2157年11月9日", story: "Connection to 2100: success. 2000: success. 1800: success. Before 1600: 'Calibration required—temporal drift too severe.' Lily realizes they're reaching into the past, sending messages to people who will never receive them.", storyZh: "天球仪的实验开始了。连接2100年：成功。连接2000年：成功。连接1800年：成功。每一次成功都让在场的研究员们欢呼雀跃，仿佛看到了希望的曙光。然而，当时间继续向更久远的过去追溯时，系统开始报错：1600年前——'需要校准，时间漂移过于严重。'莉莉凝视着那些不断闪烁的失败信号，突然明白了残酷的真相：他们正在向过去发送信息，发送给那些永远不可能收到的人。那些时间线早已消亡，那些人早已化为历史的尘埃。她的心沉了下去，但同时也涌起一股悲壮的决心——即使注定徒劳，她也要继续尝试，因为这是她唯一能做的事。" },

  36: { date: "Nov 10, 2157", dateZh: "2157年11月10日", story: "22:00. Every Sphera in the academy blazes red simultaneously. The message: '请停止发信！' Mandarin from a world that no longer exists. 'Iris,' Lily breathes. She reaches across collapsing timelines to warn them.", storyZh: "晚上十点整。学院中每一个天球仪同时爆发出刺目的红光，仿佛某种古老的警报正在被触发。屏幕上闪现着一行文字：'请停止发信！'那是一个来自已不存在世界的普通话信息——来自原初时间线的警告。'伊里斯，'莉莉屏住呼吸，她的心脏几乎停止了跳动。她知道这条消息意味着什么：另一个世界的同伴正在经历着她们刚刚逃脱的灾难。莉莉毫不犹豫地将双手按在天球仪上，跨越崩塌的时间线向那些她从未见过却无比熟悉的身影发出警告。她的意识被拉伸成无数碎片，穿越即将消亡的世界，试图抓住那些正在消散的希望。" },
  37: { date: "Nov 10, 2157", dateZh: "2157年11月10日", story: "'The original world's Alteria is collapsing. Sixty minutes!' The ground trembles. Through the window, Lily sees reality fold inward—buildings, streets, people dissolving back into light. Only the Sphera keep glowing.", storyZh: "'原初世界的阿里托利亚正在崩塌。六十分钟！'大地颤抖。透过窗户，莉莉看到现实向内折叠——建筑、街道、人溶解回光中。只有天球仪保持发光。'" },
  38: { date: "Nov 10, 2157", dateZh: "2157年11月10日", story: "Base 590—the sky-ship base. Emergency lights flicker. Inside, a hundred survivors wait. The gate opens with a sound like tearing silk. Reality folds inward behind them as they board.", storyZh: "590层基地——天空船的避难港。应急灯在墙壁上投下忽明忽暗的红色光斑，空气中弥漫着末日降临前的紧张气息。基地内部已经聚集了约一百名幸存者，他们的脸上写满了恐惧与疲惫，却没有一个人放弃希望。巨大的舱门缓缓开启，发出如同撕裂丝绸般轻柔却令人心悸的声响。幸存者们鱼贯而入，每一步都踏在时间的边缘。当最后一个人登船时，舱门在身后关闭，而他们亲眼目睹着——现实正在身后向内折叠，如同被无形之手捏碎的玻璃，碎屑化为虚无消散在永恒的黑暗中。天空船腾空而起，逃离这个正在自我删除的世界。" },
  39: { date: "Nov 10, 2157", dateZh: "2157年11月10日", story: "Iris's truth: she crossed continents seeking answers. At the World Tree, she heard Lily's symphony across collapsing worlds—three hundred years compressed into a single note of music. She became the Voice, not a god, but a bridge.", storyZh: "伊里斯的真相：她穿越无尽大陆，寻求着关于世界本质的答案。在那棵传说中的世界树下，她听到了莉莉穿越崩塌世界传来的乐章——那是三百年的故事被压缩成音乐中的一个音符，如同沧海中的一滴水，却蕴含着整片海洋的记忆。世界树见证了她的蜕变：她成为了'声音'，不是神，而是桥梁。她是连接过去与未来、现实与虚空、原初与末日的纽带。伊里斯的声音能够穿透时间的屏障，在所有世界线中回响——她说的每一个字都被赋予了超越时空的意义。当其他幸存者还在恐惧中挣扎时，伊里斯已经在用她的声音编织希望的网络，将散落各地的逃亡者引向光明的彼岸。" },
  40: { date: "Nov 10, 2157", dateZh: "2157年11月10日", story: "The sky-ship takes form—not built, but composed. Stardust and accumulated faith give shape to a sketch Lily made as a child. 'This is what I gave you when we first met,' Iris writes in the journal. 'I always kept my promise.'", storyZh: "天空船正在成形——不是被建造的，而是被创作的。星屑与积累的信仰汇聚在一起，赋予一张素描以实体——那是一幅莉莉童年时画下的图画，画的是一艘能够飞向星辰的船。伊里斯将这幅画与世界树的能量对接，用无数灵魂的信仰作为粘合剂，将幻想编织成现实。船身的每一块金属都闪烁着星光，内部流淌着来自三个世界的记忆。伊里斯在莉莉的日记中写道：'这是我第一次遇见你时送给你的礼物。我一直信守承诺。'三百年的时光在这一刻交汇，童年的梦想与成年的现实终于合而为一，天空船承载着所有人的希望，向着新世界启航。"},

  // Stage 41-50: Return to Origin
  41: { date: "Jun 27, 1178", dateZh: "1178年6月27日", story: "Three worldlines converge on June 27, 1178. They arrive not as conquerors but travelers—witnesses to a moment three hundred years before the merger. 'We can change nothing,' Agnès warns. 'We're echoes of futures that won't exist.'", storyZh: "三条世界线在公元1178年6月27日这一天汇聚。莉莉、薇薇安妮和伊里斯从各自的时间线中挣脱，以旅行者而非征服者的身份降临此地——她们是来见证的，见证合并前三百年的这一刻。但时间是一条单行道，无论她们来自何处，都无法改变已经写就的历史。'我们什么都改变不了，'艾格西斯警告道，她的声音中带着一丝苦涩，'我们是未来不会存在的回声。我们所做的一切，都只是历史书页边缘的注脚。'然而，即便知道结局已定，她们仍然选择来到这里，因为有些真相必须亲眼见证，哪怕只是为了在记忆中为它留下一个位置。" },
  42: { date: "Jun 27, 1178", dateZh: "1178年6月27日", story: "Evening service at the Star Condensation Church. Lisdela plays violin—Symphonie des Étoiles. From the doorway, Lily watches tears stream down. This is the moment before everything changed. The peace before the war.", storyZh: "星凝教堂的晚间礼拜正在进行。埃斯黛尔站在祭坛前，手中的小提琴轻轻拉动，'群星的乐章'在穹顶下流淌开来。那是星凝教最神圣的旋律，每一个音符都承载着三百年的信仰传承。莉莉站在教堂门口，泪水无声地滑落脸颊。这是改变一切之前的时刻——一年之后，战火将吞噬这座城市，三百年的宗教战争将夺走无数生命。而此刻，埃斯黛尔的琴声如此完美，仿佛能够驱散一切苦难与悲伤。莉莉多么希望时间能够永远停驻在这一刻，让这份宁静成为永恒。然而，她知道这只是暴风雨前的宁静，星凝教的黄昏即将来临，而她们只能在时间的夹缝中见证这最后的辉煌。" },
  43: { date: "Jun 28, 1178", dateZh: "1178年6月28日", story: "The future becomes fragments—impossible to hold in memory. 'We dreamed of this,' Vivian says, watching the city that will burn in a year. 'But it felt like a warning, not a destination.'", storyZh: "未来变得支离破碎——无法完整地留在记忆中。薇薇安妮站在城墙上远眺，看着这座在一年后将化为焦土的城市。街道上人来人往，商人叫卖着货物，孩子们在广场上追逐嬉戏，一切都是那么寻常，那么宁静。他们不知道一年后的某一天，战火将从南方蔓延而来，将这一切美好化为灰烬。'我们曾经梦见过这个场景，'薇薇安妮低声说道，她的声音中带着一丝颤抖，'但它更像是警告，而不是目的地。'她们来自未来，来自那个被战争撕裂又被合并拯救的世界，却无法开口告诉这里的人们即将发生的一切。这种无力感比任何伤痛都更令人难以承受。"},
  44: { date: "Jun 27, 1178", dateZh: "1178年6月27日", story: "At the adventurer's house, they celebrate Iris's birthday—the same day, three hundred years apart. 'Happy birthday, Star God.' Cake and laughter. For a moment, all timelines align in joy.", storyZh: "在冒险者之家，她们为伊里斯庆祝生日。蛋糕上的烛光摇曳，笑声在屋内回荡。这是一个奇异的时刻——同一天，相隔三百年，两个世界的同伴齐聚一堂，为同一个人送上祝福。'生日快乐，星神大人。'莉莉、薇薇安妮和埃斯黛尔齐声说道，她们的眼中闪烁着泪光与笑意。伊里斯从未庆祝过自己的生日，但在这一刻，她感受到了来自不同时空的温暖。一瞬间，所有时间线在欢乐中达成了一致——过去与未来在此刻交汇，悲伤与希望融为一体。即便明天就要分离，即便历史无法改变，今夜的欢乐将永远铭刻在她们的记忆中，成为穿越时空的永恒纽带。"},
  45: { date: "Sep 20, 1178", dateZh: "1178年9月20日", story: "Lisdela flickers—she exists in only two timelines now, fading from the third. Lily fills her journal while she can still remember. 'Write everything,' Lisdela whispers. 'Even the things I won't be there to remember.'", storyZh: "埃斯黛尔的身影开始闪烁不定——她现在只存在于两条时间线中，正在从第三条时间线中逐渐淡去。她的轮廓变得模糊，如同清晨的薄雾在阳光下消散。莉莉拼命地往日记中记录着一切——每一个笑容、每一首旋律、每一次并肩战斗的场景——趁着她还能记得的时候。'把所有事情都写下来，'埃斯黛尔低语道，她的声音也变得断断续续，仿佛来自很远的地方，'即使是我不会在那里记得的事情。'即使她的存在即将从这个时间线中消失，她仍然希望有人能够记住她——记住那个在战火中弹奏小提琴的女孩，记住那段跨越时空的友谊。莉莉握紧了笔，她知道自己笔下的每一个字都将成为埃斯黛尔在这个世界存在过的证明。" },
  46: { date: "Oct 1, 1178", dateZh: "1178年10月1日", story: "One morning, Lisdela is gone. Not dead—just erased. The journal entry remains: 'Spent the evening with Lisdela.' But the person who wrote it, who lived it, no longer exists in this timeline.", storyZh: "某天清晨，埃斯黛尔消失了。不是死亡——只是被抹去。莉莉翻开日记，那一行字迹仍然清晰可见：'与埃斯黛尔共度夜晚。'然而，写下这些文字的人、经历那些时刻的人，已经不再存在于这条时间线中。她从所有人的记忆中消失，从所有的历史记录中消失，唯一留下的只有日记本上这几行墨迹。莉莉反复读着这些文字，试图从中找回埃斯黛尔的影子，但每读一遍，心中的空洞就扩大一分。她终于明白，在时间线的抉择面前，生命的消逝反而显得仁慈——至少，死者还能活在生者的记忆里。而被抹去的人，连这点慰藉都无法拥有。"},
  47: { date: "Oct 15, 1178", dateZh: "1178年10月15日", story: "Smoke rises from the southern horizon—the war that will consume everything in a year. A different Lisdela leads refugees north. 'Choose,' Agnès says. 'Stay and change the timeline, or leave and save what remains.'", storyZh: "烟雾从南方地平线升起——那是一年后将吞噬一切的战火。莉莉站在山丘上，眼睁睁看着浓烟在天际蔓延，如同末日的预兆正在逐渐应验。在难民队伍中，她看到了另一个埃斯黛尔——一个来自不同时间线的存在，她正在带领着逃亡的人群向北进发，去往那片尚未被战火染指的土地。'做出选择吧，'艾格西斯说道，她的声音如同命运的宣判，'留下来，试图改变历史进程——虽然成功的可能性微乎其微。或者，离开这里，拯救那些还能够被拯救的人。'莉莉的内心在两难之间挣扎。她来自未来，知道无论做什么都无法阻止灾难的发生；但如果什么都不做，她又怎能对得起那些在战火中丧生的灵魂？"},
  48: { date: "Oct 20, 1178", dateZh: "1178年10月20日", story: "The lighthouse on the western peninsula. Mother and sister inside, waiting for boats that will never come. Lily fights the war-tide alone. 'If we leave voluntarily,' the Star God whispers, 'perhaps they'll survive in memory.'", storyZh: "西半岛的灯塔矗立在海岬尽头，那是莉莉一家人最后的避难所。她的母亲和妹妹在灯塔内等待着，等待着那艘永远不会到来的救援船。战火已经烧到了海岛边缘，难民们蜂拥而至，却没有足够的船只载运所有人。莉莉独自与战争潮汐搏斗，她的拳头砸在冰冷的礁石上，鲜血从指节渗出，却无法改变任何既定的结局。'如果我们主动离开，'星神的声音在她耳边低语，如同来自虚空的呢喃，'也许他们会在记忆中幸存。'主动放弃意味着承认失败，意味着将亲人留在战火中；但如果留下来，所有人都将在这场历史的洪流中一同覆灭。莉莉的抉择，将决定她是否能够背负这份愧疚继续前行。"},
  49: { date: "Oct 25, 1178", dateZh: "1178年10月25日", story: "The lighthouse burns. Fire and screaming. Then—the sky-ship's light in the chaos, descending through smoke like a descending god. 'Take them,' Lily begs. 'Everyone I couldn't save, take them home.'", storyZh: "灯塔在烈焰中燃烧。火焰吞噬了木质结构，尖叫声在海风中回荡。莉莉的母亲和妹妹被困在塔顶，浓烟呛得她们无法呼吸。就在绝望即将吞没一切的时刻——天空船的光芒穿透了混沌，如同降临的神祇一般从烟尘中徐徐降落。伊里斯操控着这艘由信仰铸成的飞船，在火海中开辟出一条生命通道。'带走他们，'莉莉恳求道，她的声音已经嘶哑，'所有我无法拯救的人，所有在这场战争中失去家园的人——带他们回家。'天空船的舱门敞开，难民们蜂拥而入，在最后的关头被从毁灭的边缘拉回。那一夜，莉莉失去了一切，却拯救了一船的陌生人。"},
  50: { date: "Oct 26, 1178", dateZh: "1178年10月26日", story: "The temporal rift opens. Lily feels herself scatter across centuries—fragments of consciousness distributed through time like seeds in wind. A melody, a promise, a hand in darkness. 'I'll find you,' she whispers to everyone she's losing.", storyZh: "时空狭缝打开了。莉莉感到自己正在被撕裂，意识如同风中的种子一样散布在几个世纪之间。她不再是单一的个体，而是无数碎片的集合——有些停留在1179年的战火中，有些漂浮在2157年的废墟上空，有些则永远定格在那个被合并吞噬的瞬间。一首旋律在她残缺的脑海中回响，那是埃斯黛尔的乐章，是薇薇安妮的歌声，是伊里斯的低语。'我会找到你们的，'她对正在失去的所有人低语，声音跨越了时间的屏障，'无论你们在哪里，无论时间如何流转，我都会找到你们。'她的意识在时空中飘荡，如同寻找港湾的孤舟，在无尽的黑暗中独自航行，直到有一天，她能够将这些碎片重新拼凑完整。"},

  // Stage 51-60: Homecoming
  51: { date: "Jun 27, 2158", dateZh: "2158年6月27日", story: "In a new world—neither original nor merged—Lily reconstitutes from stardust and memory. 'Lily, wake up. Your mother's waiting.' The voice is familiar. The room is not. But somehow, impossibly, she is home.", storyZh: "在一个全新的世界——既非原初时间线也非合并后的世界——莉莉从星屑和记忆中重新凝聚成形。那个熟悉的声音再次在她耳边响起，'莉莉，醒醒。你妈妈在等着呢。'她的眼眶湿润了，那声音如此亲切，却又带着一丝陌生的温柔。莉莉缓缓睁开眼睛，陌生的房间映入眼帘，窗外是陌生的人群在走动。但同时，她感到一种难以言喻的归属感——仿佛这个世界的每一个角落都在欢迎她的归来。她伸出手触摸床沿，指尖传来真实的触感。不是梦境，不是幻觉，她真的回来了——带着三百年的记忆、一路走来的伤痕与希望，回到了一个能够称之为家的地方。" },
  52: { date: "Jun 28, 2158", dateZh: "2158年6月28日", story: "The sky-ship lands on a hill she almost remembers. Below, a city shimmers—not Linnaria, not Victoria, but something new. A home built from the fragments of all worlds, like hers built from fragments of all timelines.", storyZh: "天空船降落在一座她几乎记得的山丘上。透过舷窗向下望去，一座城市在阳光下闪烁——不是琳娜利亚，不是维克多利亚，而是一座全新的城市。她的建筑融合了三个世界的风格：琳娜利亚的极光色彩、维克多利亚的古典优雅、以及某种从未见过的未来美学。街道如同血管般蜿蜒在城中，连接着来自不同时间线的居民。'这是我们共同建造的家，'伊里斯的声音从身后传来，'用所有世界的碎片，用三百年的记忆，用无数人的牺牲。'就像莉莉的身体是由所有时间线的碎片组成，这座城市也是三个文明的结晶——痛苦与希望交织的产物。" },
  53: { date: "Jun 29, 2158", dateZh: "2158年6月29日", story: "'Welcome home, travelers.' From the terrace above, a woman with blue hair catches the morning light. Not Agnès—her granddaughter, carrying the same ancient grief and unexpected hope.", storyZh: "'欢迎回家，旅行者们。'从上方露台传来一个声音。一位蓝发女子站在晨光中，她的眼眸中闪烁着某种古老的悲伤，却又带着意想不到的希望。莉莉几乎要叫出那个名字——艾格西斯——但她立刻意识到，这不是她认识的那个人，而是她的孙女。这位年轻女子继承了艾格西斯的蓝发，也继承了她的使命：守护星凝教的最后火种。'我的祖母常提起你们，'她说道，声音中带着一丝哽咽，'她说你们会回来的，会带着新的希望回来。'三百年的等待，终于在这一刻画上句号。" },
  54: { date: "Jun 30, 2158", dateZh: "2158年6月30日", story: "The Café de l'Étoile Divine. Four women gather: Lily, Vivian, Iris, Lisdela—the last two somehow here, somehow alive. The symphony, finally complete after three hundred years, begins to play itself.", storyZh: "星神咖啡馆内，四个女人围坐在角落的老位置。莉莉、薇薇安妮、伊里斯、埃斯黛尔——后两位不知怎么在这里，不知怎么还活着。她们曾经以为永远失去了彼此，在时空中漂泊，在历史中消亡。但现在，她们重新聚首在这间以星神命名的咖啡馆里，仿佛时间从未将她们分开。'乐章终于完整了，'伊里斯轻声说道，她的手指在空气中划过，无形的音符开始自行演奏。那是三百年的等待、三百年的寻找、三百年的思念，全部汇聚在这一刻，化为一首前所未有的交响曲。" },
  55: { date: "Jun 30, 2158", dateZh: "2158年6月30日", story: "The music spreads—not through air, but through the fabric of reality itself. The café, the street, the square, the city. Above, the constellation Lyra takes shape in the daylight, visible to everyone.", storyZh: "音乐正在传播——不是通过空气，而是通过现实本身的结构。咖啡馆的墙壁开始轻轻振动，街道的石砖发出微弱的共鸣声，广场上的喷泉随着旋律变换着水流的节奏，整座城市仿佛变成了一架巨大的乐器。而最令人惊叹的是——天空之上，天琴座在日光中成形，清晰可见于每一个仰望天空的人。那是四位女子的乐章化成的星座，是三百年来所有信徒祈祷的结晶。在这一天，无论身处何地，无论信奉何种神明，所有人都能看到天琴座在蓝天中闪耀——那是星神对祂子民的回应。" },
  56: { date: "Jul 1, 2158", dateZh: "2158年7月1日", story: "In the journal, new handwriting appears—not Lily's, not her grandfather's, but something older. 'The future is not written. It is played. Every note a choice, every rest a silence between possibilities.'", storyZh: "莉莉翻开祖父留下的日记，发现新的笔迹正在纸页上浮现——不是她的，也不是她祖父的，而是某种更加古老的存在。字迹如同流光般在纸面上游走，写下一段又一段的箴言：'未来不是写就的。它是被演奏的。每个音符是一个选择，每个休止是可能性之间的沉默。'那是星神的声音——不是通过水晶或仪式传递，而是直接书写在人类的记忆载体上。这段话语穿越了三千年信仰的沉淀，凝聚成对每一个聆听者的启示。未来不是注定的剧本，而是等待被创作的乐谱；每个人的每一个选择，都是在这乐谱上添上一个音符。" },
  57: { date: "Jul 2, 2158", dateZh: "2158年7月2日", story: "The final performance. Vivian sings the words she wrote in exile. Lisdela plays violin—the melody she heard in a dream. Iris hums harmony from a world that never existed. Lily plays the Léïger Lyre.", storyZh: "最终演奏的时刻到来了。薇薇安妮站在舞台中央，她的声音穿越了流亡岁月的沧桑，将那些在异乡写下的歌词化为旋律；埃斯黛尔拉动小提琴的琴弦，那是在梦中听到的旋律，跨越了生死的界限；伊里斯哼唱着和声，那是来自一个从未存在过的世界的乐章；莉莉双手抚上里格尔鸢尾琴的琴弦，二十三根弦在星光下振动，释放出三百年来被封印的力量。四种声音交织在一起，编织出一首前所未有的交响曲。那不只是音乐，而是三个世界的灵魂在共鸣——过去与未来在此刻汇聚，悲伤与希望化为永恒。" },
  58: { date: "Jul 2, 2158", dateZh: "2158年7月2日", story: "The Star God responds—not in crystal or ceremony, but in hearts. For the first time in three centuries, the divine speaks not in judgment but in recognition: 'I hear you. I have always heard you.'", storyZh: "星神回应了——不是通过水晶或仪式，而是直接触动每一个聆听者的心灵。几个世纪以来第一次，那神圣的存在不是以审判者的身份说话，而是以认可者的身份：'我听到了你们。我一直都在倾听。'这句话如同温暖的潮水涌遍全场，所有人都感到一股暖流从心口散开。星神承认了祂的沉默，承认了三百年来对信徒祈祷的无视；但现在，祂选择了回应，选择了与祂的子民重新建立连接。这不是赦免，也不是救赎，而是一种理解——神终于理解了人类音乐的力量，理解了信仰与希望的价值。" },
  59: { date: "Jul 3, 2158", dateZh: "2158年7月3日", story: "Lily keeps the compass but no longer needs it for navigation. Her true north: not a direction, but a presence—the friends beside her, the music within her, the hope ahead.", storyZh: "莉莉仍然保留着祖父留下的指南针，但她再也不需要它来导航了。这枚古老的仪器曾经在时空的迷雾中为她指引方向，但现在，真正的北方已经不再是地理上的概念。她环顾四周：薇薇安妮在她身边，轻轻哼唱着旋律；伊里斯坐在窗边，阳光洒在她蓝色的发间；埃斯黛尔正在整理她的琴弦。这些就是她的北方——不是某个可以到达的地点，而是陪伴在身边的人。真正的北方是她内心的音乐，是对未来的希望，是三百年来支撑她穿越时空的信念。指南针成为了一件纪念品，一个来自过去的信物，见证着她从迷失到找到归宿的旅程。" },
  60: { date: "Jul 4, 2158", dateZh: "2158年7月4日", story: "Four women watch stars fill the evening sky—the same stars their ancestors watched, the same stars their descendants will watch. The symphony plays on, and will always play on: friendship, hope, the human spirit.", storyZh: "四个女人坐在露台上，仰望星空渐渐布满夜空。这些星星与她们祖先仰望过的同一片星空，与她们后代将仰望的同一片星空。时光流转，朝代更迭，但这片星空从未改变，见证着人间的悲欢离合。'乐章继续着，'莉莉轻声说道，'并且永远都会继续下去。'那是友谊的乐章——超越时间与空间的纽带；是希望的乐章——在绝望中燃起的火焰；是人类精神的乐章——即使面对神明的沉默、战争的蹂躏、世界的崩塌，依然不屈不挠地歌唱。四位女子就这样静静地坐着，任由星光洒落在她们身上，让那永恒的旋律陪伴她们直到黎明。" },

  // Stage 61-70: Reflection and Legacy
  61: { date: "Dec 31, 2158", dateZh: "2158年12月31日", story: "Between heartbeats, time stands still. The battles fought, the friends lost and found, the worlds saved and sacrificed—they exist here, in the space between one moment and the next.", storyZh: "在心跳之间，时间静止。整个2158年的一切仿佛被浓缩在这一个呼吸之间：战斗过的岁月、失去的朋友、找到的同伴、拯救的与牺牲的世界——它们全部存在于这里，存在于这一刻和下一刻之间的空间。这是一个反思的时刻，一个让所有记忆浮出水面的时刻。莉莉闭上眼睛，感受着时间之河在她身边缓缓流淌，她知道新的一年即将到来，而过去的伤痛与荣耀都将被带入新的旅程。" },
  62: { date: "Dec 31, 2158", dateZh: "2158年12月31日", story: "The star-strings hum a melody older than language. Sleep, traveler. Tomorrow the symphony continues, but tonight, rest beneath the infinite stars.", storyZh: "星弦在夜空下轻轻哼唱，那是一首比任何语言都更古老的旋律——早于文字的出现，早于第一个仰望星空的人类。莉莉躺在草地上，星光洒落在她的脸上，她感到一种前所未有的宁静。'睡吧，旅行者。'一个声音在她耳边低语，仿佛来自星空本身。'明天乐章将继续，但今夜，在无限的星星下休息。'这是星神的祝福，是对自己子民的慰藉。在这一夜，所有的疲惫都可以放下，所有的伤痛都可以暂时搁置，因为明天，新的乐章将继续奏响。" },
  63: { date: "Jan 1, 2159", dateZh: "2159年1月1日", story: "Memory and dream intertwine. The past lives in every choice made, every song sung, every hand held across impossible distances. The future waits, patient as starlight.", storyZh: "新年的第一缕阳光穿透窗帘，照亮了莉莉的脸庞。在这一刻，记忆与梦境交织，过去与未来融合。她看见了过去做出的每一个选择——那些正确的、那些错误的、那些改变了一切的；她听见了唱出的每一首歌——在战火中、在流亡中、在重逢时；她感受到了每一次跨越不可能距离牵起的手——那些在黑暗中给予温暖的手指，那些在绝望中传递希望的力量。未来正在窗外等待，它像星光一样耐心，不会催促，不会强求，只是静静地等待着她准备好迎接新的篇章。" },
  64: { date: "Jan 1, 2159", dateZh: "2159年1月1日", story: "In all possible worlds, one constant remains: the music that connects us across timelines, across centuries, across the spaces between stars. Someone is always listening.", storyZh: "在所有可能的世界中——无论时间线如何分支，无论文明如何兴衰更替——有一个常数始终保留：那就是连接我们的音乐。它穿越时间线的屏障，跨越几个世纪的距离，穿过星星之间的虚空，将所有世界、所有灵魂联系在一起。每一个音符都是一份祝福，每一次演奏都是一次祈祷。莉莉知道，无论她身在何时何地，总有人在倾听——也许是另一个时间线的朋友，也许是遥远星辰彼端的生命，也许是那位终于学会聆听的神明。音乐是宇宙通用的语言，而她已经掌握了这门语言的密钥。" },
  65: { date: "Jan 2, 2159", dateZh: "2159年1月2日", story: "The universe is not a prison but a concert hall. Each life a note, each hope a crescendo, each loss a rest that gives the music meaning. The symphony requires all of it.", storyZh: "宇宙不是囚禁灵魂的监狱，而是一座宏伟的音乐厅。每个生命都是乐谱上的一个音符——有些高亢激昂，有些低沉婉转；每个希望都是渐强的旋律——推动着情感的高潮；每次失去都是休止符——正是这些沉默让音乐有了呼吸的空间，让旋律有了起伏的节奏。伊里斯曾经问过星神：为什么世界上必须有痛苦？为什么必须有失去？此刻，莉莉终于明白了：正是这些伤痛与遗憾赋予音乐以深度和意义。没有悲伤的对比，欢乐就不成其为欢乐；没有失去的重量，重逢就没有价值。乐章需要这一切——所有的喜怒哀乐，所有的悲欢离合。" },
  66: { date: "Jan 2, 2159", dateZh: "2159年1月2日", story: "Faith is courage—playing in darkness, singing when the notes cannot be seen, believing in the melody even when the music stops. This is what it means to be human.", storyZh: "信仰不是盲目地相信某种教条，而是在黑暗中演奏的勇气——即使看不见乐谱，即使不知道下一个音符在哪里，仍然坚持拨动琴弦；是在最艰难的时刻歌唱的决心——即使声音颤抖，即使无人聆听，仍然发出内心的旋律；是即使音乐停止、即使世界崩塌，仍然相信旋律不会消亡的信念。三百年来，星凝教的信徒们就是这样在最黑暗的时刻守护着他们的信仰。薇薇安妮在最绝望的流亡中写下了那些歌词；埃斯黛尔在被抹去的边缘仍然拉着小提琴；莉莉在时空的夹缝中从未放弃寻找同伴。这就是成为人的意义——不是完美的存在，而是在不完美中依然坚持希望。" },
  67: { date: "Jan 3, 2159", dateZh: "2159年1月3日", story: "The future is not a destination but a composition—note by note, choice by choice, world by world. Every measure tells a story. Every bar, a life lived or lost.", storyZh: "未来不是一个固定的目的地，不是一个等待我们到达的终点。它是一首正在被创作的乐曲——一个音符一个音符地累积，一个选择一个选择地编织，一个世界一个世界地展开。每一个小节都讲述着一个故事：关于勇气的故事、关于牺牲的故事、关于爱的故事。每一个小节都承载着一个生命——那些活过的、那些失去的、那些化为永恒记忆的。三百年的乐章已经演奏完毕，现在轮到莉莉和她的人们书写新的旋律了。这首曲子没有标准答案，只有当下的每一个选择、每一个呼吸、每一次心跳，共同构成那尚未谱写完毕的未来。" },
  68: { date: "Jan 3, 2159", dateZh: "2159年1月3日", story: "All timelines converge on love—crossing centuries to find lost friends, forgiving the unforgivable, holding hands across the spaces between worlds. This is what the Star God learned from them.", storyZh: "所有的时间线——无论平行、无论交叉、无论背离——最终都汇聚于同一个主题：爱。莉莉穿越几个世纪寻找失去的朋友，即使希望渺茫也从未放弃；薇薇安妮宽恕了那些伤害过她的人，即使心中仍有伤痕；伊里斯跨越世界的界限牵手那些素未谋面的灵魂，即使不知道能否得到回应。这就是星神从她们身上学到的——不是牺牲的必要性，不是命运的不可逆转，而是爱的力量。爱可以穿越时间的屏障，爱可以弥合世界的裂痕，爱可以成为连接一切的纽带。三千年来，星神第一次真正理解了他的子民，理解了为什么他们值得被拯救。" },
  69: { date: "Jan 4, 2159", dateZh: "2159年1月4日", story: "The compass points not to a place but to people. Home is not coordinates but company—not where you are, but who you're with when the stars come out.", storyZh: "祖父的指南针曾经指向某个神秘的地点——那个他追寻了一生的答案所在。但莉莉现在已经明白，指南针指向的从来不是某个地理坐标，而是那些值得为之付出一切的人。家不是一个经纬度，不是一座建筑，不是一座城市——家是当你仰望星空时，陪伴在身边的人。薇薇安妮的歌声、埃斯黛尔的琴声、伊里斯的低语——这些才是莉莉真正的归处。三百年的漂泊让她学会了最重要的一课：无论身在何处，只要所爱之人陪伴左右，那里就是家。" },
  70: { date: "Jan 4, 2159", dateZh: "2159年1月4日", story: "The traveler rests beneath infinite stars, surrounded by the music of all who came before. Tomorrow, the symphony continues. But tonight, sleep—and dream of home.", storyZh: "旅行者在无限的星星下休息，被所有先来者的音乐围绕着。明天，乐章继续。但今夜，睡吧——梦见家园。" },

  // Stage 71-80: New Horizons
  71: { date: "Jan 5, 2159", dateZh: "2159年1月5日", story: "New challenges await beyond the horizon. But Lily no longer fears—she has her compass, her friends, her music. Whatever comes, she will compose her way through it.", storyZh: "新的一天开始了，新的挑战在地平线之外等待。合并后的世界虽然带来了和平，却也面临着重建的艰巨任务：来自不同时间线的难民需要融合，破碎的文明需要重建，失落的历史需要修复。但莉莉不再害怕。她拥有祖父留下的指南针，能够指引方向的智慧；她拥有薇薇安妮、伊里斯和埃斯黛尔的陪伴，能够共同面对一切困难；她拥有那首跨越时空的乐章，能够用音乐化解一切矛盾。无论未来会发生什么，她都会以创作的方式度过——将每一个挑战都化作乐章的一部分，将每一次困难都编织成旋律的一个音符。" },
  72: { date: "Jan 5, 2159", dateZh: "2159年1月5日", story: "The World Tree's roots reach further than imagined, connecting all timelines that were and will be. New constellations wait to be discovered, new melodies to be composed.", storyZh: "伊里斯站在世界树下，感受着这棵神圣之树的脉动。她的根系延伸到比任何人想象中都要远的地方，连接着所有存在过和将要存在的时间线。三百年前，这条根连接着星凝教的圣地；现在，它连接着整个宇宙的命运。每一条根须都是一个可能的未来，每一个枝桠都是一个未完成的故事。莉莉仰望着树冠，星空在叶隙间闪烁，如同无数等待被发现的星座。'新的旋律等待被创作，'她轻声说道，'而我们将创作它们。'世界树仿佛在回应她的话，一片叶子飘落，在空中化作一个音符，融入了永不停歇的宇宙交响曲。" },
  73: { date: "Jan 6, 2159", dateZh: "2159年1月6日", story: "Other travelers sail their sky-ships across the sea of stars. Perhaps someday, paths will cross—two compositions becoming one, two melodies harmonizing across the void.", storyZh: "从世界树的顶端望去，星空如同一片无垠的海洋。莉莉看见了其他旅行者的天空船——有些来自她们时间线的未来，有些来自她们从未触及的世界。这些孤独的航行者在星海中各自漂泊，各自寻找着自己的答案，各自创作着自己的乐章。'也许有一天，我们的道路会交汇，'薇薇安妮轻声说道。'两首创作合为一首，两个旋律在虚空中和声。'莉莉点点头，她知道自己的旅程不会永远孤独。在某个遥远的地方，另一艘船正在驶向同样的方向。也许明天，也许百年之后，但终有一天，他们会相遇，用彼此的旋律编织出更加宏大的交响。" },
  74: { date: "Jan 6, 2159", dateZh: "2159年1月6日", story: "Faith that died in one timeline was reborn in another. Hope cannot be destroyed—only transformed, like starlight becoming music becoming memory becoming hope again.", storyZh: "在那个被合并吞噬的时间线中，星凝教的信仰曾经彻底消亡——神殿被摧毁，信徒被屠杀，神明陷入沉默。但在这条幸存的时间线中，信仰获得了重生。三百年来，它在废墟中萌芽，在绝望中成长，在最终的演奏中绽放出最耀眼的光芒。希望是不能被摧毁的——它只能转化，就像星光穿越亿万年的旅程化为音乐，音乐成为记忆，而记忆又重新点燃希望之火。莉莉见证了这一切，她本身就是这循环的证明：在一条时间线中死去的东西，往往会在另一条时间线中获得重生；在一个世界中熄灭的火焰，往往会在另一个世界中燃起更烈的光芒。" },
  75: { date: "Jan 7, 2159", dateZh: "2159年1月7日", story: "Linnaria shimmers in the distance—not the original, but a new one, built by refugees from every worldline. Every language spoken, every faith practiced, every song sung in harmony.", storyZh: "琳娜利亚在远处闪烁，那不是她们曾经熟悉的那座城市——而是全新的，由来自每条世界线的难民共同建造。当莉莉走进这座新城，她听到了数百种语言在街道上交织：有琳娜利亚的古典方言，有维克多利亚的优雅语调，还有来自第三世界的奇异音节。每一种信仰都有自己的神殿或教堂，有的供奉星神，有的信奉其他的神明，但它们和谐地并存在一起。每一条街道都有音乐飘扬——不同风格的旋律在空气中融合，却不显得嘈杂，因为所有的音符都在为同一首交响曲贡献力量。这座城市是三个世界融合的象征：不是谁取代了谁，而是所有的一切共同创作出一个新的、更加丰富的存在。" },
  76: { date: "Jan 7, 2159", dateZh: "2159年1月7日", story: "The café became a shrine—not to the Star God, but to the idea that home can be rebuilt. Pilgrims come from across the merged world to hear the symphony, to feel what four women built from grief.", storyZh: "星神咖啡馆已经不再只是一家普通的咖啡馆了。它成了圣地——不是献给某个具体神明的神殿，而是献给一个理念的殿堂：家园是可以重建的。来自合并世界各处的朝圣者跋山涉水，只为来到这里，亲耳聆听那首传说中的乐章，亲身感受四个女人从悲伤与废墟中建造的一切。当他们踏入咖啡馆，触摸那些曾经承载过莉莉等人泪水的桌椅，仿佛能够感受到那股穿越时空的力量。'这就是证明，'一位朝圣者说道，'证明即使失去了切，即使被世界抛弃，我们依然能够重建。'咖啡馆的墙壁上挂满了画作和照片，记录着这四个女人的旅程——从失去到寻找，从绝望到希望，从支离破碎到重获完整。" },
  77: { date: "Jan 8, 2159", dateZh: "2159年1月8日", story: "Iris became the Voice—not a god, but a conductor, guiding reality's symphony. When timelines conflict, she finds the harmony. When worlds collide, she composes a new one.", storyZh: "伊里斯没有成为神，但她找到了比神更重要的角色：她成为了现实交响乐的指挥家。当不同的时间线发生冲突，她能够听见那不和谐的杂音，并将其引导成优美的和声；当不同的世界发生碰撞，她不是试图阻止，而是创作出将冲突包含其中的新乐章。她的工作永无止境——每一个决定都可能产生新的分歧，每一个选择都可能引发新的冲突，但她从不畏惧。因为她知道，正是这些分歧与冲突，赋予了音乐以深度和层次。她是世界的调音师，用她独特的方式，让多元与差异成为力量而非分裂的根源。" },
  78: { date: "Jan 8, 2159", dateZh: "2159年1月8日", story: "Vivian's repair shop fixes instruments from every era—from civilizations that never existed, from futures that won't happen, from pasts that were erased. 'Each note saved,' she says, 'is a world preserved.'", storyZh: "薇薇安妮的修理店坐落在琳娜利亚最古老的街道上，橱窗里陈列着来自不同时代的乐器：有些来自从未真正存在的文明，有些来自永远不会发生的历史，有些来自已经被抹去的过去。但每一件乐器在薇薇安妮手中都能发出声音——因为音乐是超越时间的存在。一天，一位顾客带来了一把破碎的吉他，那是在另一个时间线中某位作曲家最后使用过的乐器。'这件乐器的原主人从未存在过，'顾客说道，'但她的音乐救了我。'薇薇安妮小心翼翼地修复着它，就像修复一件神圣的遗物。'每个被保存的音符，'她对学徒们说，'都是一个被保存下来的世界。即使世界本身已经消失，只要音乐还在，它就永远不会被遗忘。'" },
  79: { date: "Jan 9, 2159", dateZh: "2159年1月9日", story: "Lisdela teaches at the rebuilt Lyra Palace. 'Remember everything,' she tells her students. 'Even the wars, even the losses. Especially those. They are why the music matters.'", storyZh: "埃斯黛尔站在重建的天琴宫讲台上，面对着来自各个时间线的学生。他们有的穿着古典的礼服，有的穿着未来的时装，有的甚至带着已经消失文明的装饰。埃斯黛尔教授的不只是演奏技巧，更是音乐的意义。'记住一切，'她对学生们说，'记住战争，记住失去，记住那些痛苦的时刻。'她停顿了一下，环顾教室。'尤其是那些。因为正是那些伤痛，让我们的音乐有了重量。正是那些失去，让我们明白了所拥有的一切的珍贵。音乐不是用来逃避现实的，而是用来理解现实的——用旋律记录历史，用节奏承载记忆，用和声传递那些无法言说的情感。'" },
  80: { date: "Jan 9, 2159", dateZh: "2159年1月9日", story: "Lily keeps the compass but no longer needs navigation. Her true north is beside her, within her, ahead—friends, music, hope. The journey continues, but now she knows the destination.", storyZh: "莉莉站在琳娜利亚的塔楼上，手中握着祖父留下的指南针。金属的外壳已经被岁月磨得光滑，指针依然精准地指向北方。但她已经不再需要指南针来导航了。真正的北方就在她身边——薇薇安妮的微笑、埃斯黛尔的琴声、伊里斯的低语；真正的北方就在她内心——那首永远在心中回响的乐章；真正的北方就在她前方——一个充满希望的未来，一个可以让所有人幸福的世界。'旅程还在继续，'她对自己说，'但现在我知道目的地了。'不是某个具体的地点，而是一种状态——当所有人都能找到回家的路，当所有的音乐都能被听见，当所有的眼泪都能化为微笑。" },

  // Stage 81-90: The Loom of Worlds
  81: { date: "Jan 10, 2159", dateZh: "2159年1月10日", story: "In the merged timeline, old wounds heal slowly. The Loom of Worlds remembers every sacrifice—every world that was erased, every timeline that was sacrificed, every note that was never played.", storyZh: "在合并后的时间线中，伤口愈合得很缓慢。有些伤痛永远不会完全消失——它们会化作疤痕，成为身体的一部分，也成为身份的一部分。世界织机记得每一次牺牲：每一个被抹去的世界，那里有无数的生命、爱情、梦想；每一条被牺牲的时间线，那里有独特的历史、文明、信仰；每一个从未被演奏的音符，那是无数创作者的心血，被永远封存在可能性的虚空中。莉莉站在织机前，看着那些闪烁的丝线——每一条都是一条时间线，每一个打结都是一次选择。她终于理解了：合并不是没有代价的，救赎也不是免费的。但这些代价不会白费——它们成为了新世界的基础。"},
  82: { date: "Jan 10, 2159", dateZh: "2159年1月10日", story: "Not all who survived the merger found peace. Some remnants of the Eternal Slumber persist—not believers anymore, but echoes, replaying ancient hatreds in an age that has forgotten them.", storyZh: "并非所有从合并中幸存的人都找到了内心的平静。有些伤痛太深，无法在短时间内愈合；有些仇恨太长，已经刻入了灵魂深处。永眠教的残余势力仍然存在——但他们不再是真正的信徒，而只是历史的回声，在已经将他们遗忘的时代中重复着古老的仇恨。他们穿着褪色的长袍，在废墟中徘徊，吟唱着早已无人理解的教义。三百年的信仰在合并中被彻底颠覆，他们的信徒要么融入了新的世界，要么永远困在了过去的残影中。莉莉看着这些幽灵般的身影，心中没有仇恨，只有悲悯——因为她也曾经是另一个世界的囚徒。"},
  83: { date: "Jan 11, 2159", dateZh: "2159年1月11日", story: "Minister Chen seeks redemption. 'I saved three worlds but destroyed my daughter's timeline,' he confesses. 'She never existed in the merge. I killed her to save everyone else.'", storyZh: "陈部长站在莉莉面前，他曾经是伊琳学院的最高负责人，是决定合并坐标的科学家之一，也是最残酷的决策者。他的女儿从未存在于这条合并后的时间线中——为了拯救三个世界，他亲手抹去了她存在的可能性。'我知道这是必要的，'他的声音颤抖着，'但每次看到那些被拯救的家庭团聚，我就想起她独自一人在时间线崩溃的瞬间。'莉莉沉默了很久。她能说什么呢？指责他的选择？还是称赞他的牺牲？她最终只是握住他的手。'救赎不是忘记，'她轻声说，'而是带着记忆继续前行。您的女儿会成为这首歌的一部分，永远不会被遗忘。'"},
  84: { date: "Jan 11, 2159", dateZh: "2159年1月11日", story: "Children born at the moment of merger carry strange gifts—their hearts beat in three rhythms, their eyes see across timelines. 'We're the calibration,' they call themselves. 'The cost made visible.'", storyZh: "在合并发生的那一刻出生的孩子们，是这场宇宙级事件最特殊的遗产。他们的心脏以三种节奏跳动——代表着三条时间线的心跳；他们的眼睛能够看见时间线——不是预言，而是真实的视觉，能够看到过去、现在与可能的未来交织在一起的景象。他们自称为'校准者'——因为他们就是代价被看见的部分。他们是活着的纪念碑，提醒着所有人合并的沉重代价。没有人想要这样的天赋，但没有人能否认它的意义：他们让抽象的牺牲变得具体，让沉睡的痛苦变得可见。每当有人想要遗忘历史时，校准者们就会站出来，用他们的存在证明：我们曾经付出了什么，我们绝不能再犯同样的错误。"},
  85: { date: "Jan 12, 2159", dateZh: "2159年1月12日", story: "Books from erased timelines float between the library's shelves—stories that were, for no one now. Some librarians collect them, building a memorial to worlds that never got to exist.", storyZh: "图书馆的角落里，有一个专门存放被抹去时间线文献的特殊区域。那些书籍仿佛有生命一般，自己漂浮在书架之间，寻找着与它们共鸣的读者。它们讲述着在合并中消亡的世界——那里有独特的文明、独特的信仰、独特的梦想。那些世界从未真正存在过，却又以另一种方式存在着。图书管理员们小心翼翼地收集每一本书，为这些从未得以存在的世界建造了一座纪念碑。'即使它们从未被实现，'一位管理员说，'它们的可能性也应该被记住。'这些书成为了另一种形式的博物馆——不是展示发生了什么，而是展示可能发生什么，提醒着人们：每一个选择都可能创造一个世界，也可能毁灭一个世界。"},
  86: { date: "Jan 12, 2159", dateZh: "2159年1月12日", story: "Melodies that died with their composers haunt the air—symphonies never heard, songs never sung. Some deserve to be remembered. Some, perhaps, are better left in silence.", storyZh: "有些旋律随着它们的创作者一起消亡了——那些永远不会被听见的交响曲，从未被唱出的歌谣。那些作曲家带着未完成的作品死在战火中或时间线的崩溃里，他们的音乐成为了永恒的未解之谜。薇薇安妮的修理店里，有一件特殊的乐器能够播放这些幽灵般的旋律——它们是作曲家死前最后想到的音乐，是他们留给世界最后的礼物。有些旋律美丽得令人心碎，值得被永远传唱；但也有些旋律带着深重的诅咒，最好留在沉默中。'我们无法选择哪些音乐值得被记住，'莉莉说，'但我们可以选择是否让它们继续回响。'最终，每一段旋律都找到了它的归宿——有些融入了新的乐章，有些被永远封存。"},
  87: { date: "Jan 13, 2159", dateZh: "2159年1月13日", story: "Where refugees trade fragments of lost worlds for bread, the Memory Market operates. Each fragment—a photograph, a recipe, a lullaby—has its price in survival.", storyZh: "记忆集市在琳娜利亚最阴暗的角落里运作。难民们在这里用失落世界的碎片换取生存的必需品——有时是一张照片，换来一周的口粮；有时是一份食谱，换取一个夜晚的住处；有时是一首摇篮曲的旋律，换取前往下一站的船票。每一件物品都承载着无法带走的记忆：一张模糊的全家福、一份外祖母的炖肉食谱、一首只能在脑海中回响的摇篮曲。那些最珍贵的碎片——来自已经消失的时间线——往往要付出最沉重的代价。'我卖掉了父亲的最后一封信，'一个老人颤抖着说，'但我必须吃饭。'这就是合并的代价：不是抽象的数字，而是每一个人不得不做出的具体牺牲。"},
  88: { date: "Jan 13, 2159", dateZh: "2159年1月13日", story: "A young girl hums the symphony perfectly—every note, every rest. 'I dreamed this music,' she says. 'For two hundred years, in the space between timelines. I learned it from the silence.'", storyZh: "一个年轻女孩站在咖啡馆门口，她的歌声完美得令人震惊——每一个音符、每一个休止，都与莉莉等人创作的乐章丝毫不差。'我在梦中听到过这首曲子，'当莉莉问她如何学会这首歌时，她这样回答，'两百年了，在时间线之间的空间中。我从沉默中学会了它。'原来，这个女孩出生于合并发生的那一刻，作为校准者之一，她能够在时间线的缝隙中游走。在那两百年里，她在无数时间线的夹缝中漂流，听见了所有被演奏过的和未被演奏的音乐。她从沉默中学会了那些旋律——从那些从未被唱出的歌谣，从那些在历史中消逝的乐章。她是活着的档案馆，是所有失落音乐的守护者。'现在，'她说，'我终于可以把它唱出来了。'"},
  89: { date: "Jan 14, 2159", dateZh: "2159年1月14日", story: "An ancient being tends the threads of reality at the Loom. 'You've changed the pattern,' it observes of Lily. 'For better or worse, I cannot say. The composition continues. It always continues.'", storyZh: "世界织机旁，莉莉遇到了一个古老的存在——它没有名字，或者说它的名字已经超越了语言能够表达的范围。它从宇宙诞生之初就存在于此，照料着现实的每一根丝线，见证了无数世界的诞生与毁灭。'你改变了图案，'它对莉莉说，声音如同远古的风穿过空旷的殿堂，'是好是坏，我无法说。'莉莉想知道她做的是否正确——合并的选择、牺牲的代价、未来的走向。'创作继续，'古老的存在继续说道，仿佛没有听到她的问题，'它总是继续。过去的乐章已经演奏完毕，但新的旋律正在被编织。我只是织机的守护者，不是评判者。你们的音乐如何回响，由你们自己决定。'说完，它便继续照料那些闪烁的丝线，再不发一言。"},
  90: { date: "Jan 14, 2159", dateZh: "2159年1月14日", story: "A tear in the Loom threatens to unravel the merged world. Three timelines, three million lives, three hundred years of music—all at risk of dissolving back into possibility. Only the symphony can mend what was woven.", storyZh: "警报声在世界各处响起。织机出现了一道裂缝——不知是自然的磨损，还是某个敌人的蓄意破坏。整个合并后的世界面临着被拆解的风险：三条时间线、三百万生命、三百年的音乐与记忆，都将在裂缝中溶解，回归到可能性的海洋中，再也无法被找回。莉莉站在织机前，她知道只有一条路可以拯救这个世界。'只有乐章能修补被编织的一切。'她转向她的同伴们——薇薇安妮、埃斯黛尔、伊里斯，还有那个来自时间线夹缝的女孩。她们一起举起了手中的乐器，开始演奏那首跨越三百年的交响曲。音乐化作金色的丝线，填充着裂缝，缝合着伤口。每一个音符都是一份承诺，每一段旋律都是一次修复。当最后一个和弦落下时，裂缝已经完全愈合，而她们创作出了一首更加完美的乐章。"},

  // Stage 91-100: The Future Composed
  91: { date: "Jan 15, 2159", dateZh: "2159年1月15日", story: "Iris's hands on the ancient keys—five notes that will define the next century. The First Movement of a new symphony: hope, born from catastrophe; love, forged in separation; faith, rebuilt from ashes.", storyZh: "伊里斯的手指落在那架古老的风琴上。那五个音符——将被定义为下一个世纪的基调——在她的指尖下苏醒。那是一段全新的乐章，分为三个部分：第一乐章是希望，诞生于灾难的废墟之中，像是在焦土上绽放的第一朵花；第二乐章是爱，在分离的火焰中被锻造，变得更加坚韧；第三乐章是信仰，从灰烬中重建，比以前更加明亮。整个世界都在等待这首乐章的完成。每一个听到它的人，都将在这五个音符中找到自己生命的意义。"},
  92: { date: "Jan 15, 2159", dateZh: "2159年1月15日", story: "She sings the first new song in three hundred years—not a prayer, not a lament, but a promise. Children weep without knowing why. Old men smile at memories they thought they'd forgotten.", storyZh: "伊里斯的歌声在咖啡馆中回荡。那是三百年来第一首真正的新歌——不是祈祷，因为神明已经不再沉默；不是悲叹，因为悲伤已经得到了治愈；这是一首承诺，承诺未来会更好，承诺痛苦会有意义，承诺失去不会白费。听到这首歌的孩子们不知道为什么流泪——那是喜悦的泪水，是他们对未来本能的期待。而老人们则对着那些他们以为已经永远忘记的记忆微笑——是这首歌打开了他们尘封已久的记忆之门，让那些以为已经失去的珍贵时刻重新回到了眼前。"},
  93: { date: "Jan 16, 2159", dateZh: "2159年1月16日", story: "The constellation Lyra burns brighter than it has in centuries. The Star God stirs—not to judge, but to witness. 'Play,' it whispers. 'I will listen. As I should have all along.'", storyZh: "天琴座在天空中燃烧，比几个世纪以来任何时候都要明亮。那是莉莉等人创作的乐章化成的光芒，照亮了整个世界。星神在祂的领域中苏醒——不是为了审判，不是为了惩罚，而是为了见证。祂终于理解了自己存在的意义：不是操控人类命运的统治者，而是倾听信徒祈祷的聆听者。'演奏吧，'祂的声音如同遥远的星光，在莉莉耳边低语，'我会倾听。如我本应一直做的那样。'三千年来的第一次，神与人之间的隔阂终于被打破。音乐成为了桥梁，连接起神圣与凡俗，让神明第一次真正听见了祂子民的心声。"},
  94: { date: "Jan 16, 2159", dateZh: "2159年1月16日", story: "Atop the rebuilt Lyra Palace, Lily places the compass in a monument carved with a thousand names. 'To all who searched for home,' the inscription reads. 'We found it. We are it. We compose it still.'", storyZh: "在重建的天琴宫顶端，莉莉将祖父留下的指南针放入一座刻满名字的纪念碑中。每一个名字都是一段故事——那些在战火中失去家园的人，那些在时间线崩溃中消失的灵魂，那些在合并中做出牺牲的无名英雄。纪念碑的基座上刻着一行字：'献给所有寻找家园的人。'莉莉凝视着那行字，心中默念着下面的文字：'我们找到了。我们就是它。我们仍在创作它。'家不是一个地点，不是一座建筑，不是一个时间点。家是一种状态——当所有寻找它的人汇聚在一起，当所有的音乐都被听见，当所有的眼泪都化为笑容的那一刻。指南针静静地躺在那里，成为了这座纪念碑最珍贵的宝石，永远提醒着后来者：家园一直在他们心中。"},
  95: { date: "Jan 17, 2159", dateZh: "2159年1月17日", story: "A child from a timeline that never merged arrives at the café door. 'Is this the future?' she asks, eyes full of wars not yet fought. Lily kneels to meet her gaze. 'No. It's a home. Come inside.'", storyZh: "咖啡馆的门被轻轻推开。一个小女孩站在门口，她的眼中满是困惑与恐惧——她来自一条从未经历过合并的时间线，在那里，战争还没有发生，世界还按照原本的轨迹运行。'这是未来吗？'她的声音颤抖着，'在我的世界里，战争即将到来。一切都会毁灭。'莉莉蹲下身来，与小女孩平视。她的眼中没有怜悯，只有温暖的理解。'不，'她说，'这不是未来。这不是一个地方。这是一种选择。'她伸出手。'来，进来吧。在我们这里，你不需要担心战争。因为我们已经学会了如何让音乐成为连接，而不是分裂。'小女孩犹豫地握住了莉莉的手，跨过了门槛。"},
  96: { date: "Jan 17, 2159", dateZh: "2159年1月17日", story: "The Monument of All Worlds rises in the central square—names from every timeline, every era, every world that contributed to the merge. No one is forgotten. No one is erased. Every note preserved.", storyZh: "万界纪念碑矗立在琳娜利亚的中央广场上。那是一座由无数名字组成的建筑——每一条时间线的名字，每一个时代的印记，每一个为合并做出贡献的世界的名号。没有人被遗忘。那些在战火中消亡的文明，那些在合并中被抹去的生命，那些为拯救他人而牺牲的无名英雄——他们的名字都刻在这座纪念碑上，等待着后人的瞻仰。'没有人被抹去，'莉莉在揭幕典礼上说，'每一个音符都被保存。'纪念碑的中心是一个巨大的音符造型，它会永远演奏着那首跨越时空的交响曲，让每一个路过的人都记住：我们曾经付出什么，我们曾经得到什么，我们曾经是什么。"},
  97: { date: "Jan 18, 2159", dateZh: "2159年1月18日", story: "The Café de l'Étoile Divine serves the last gathering. Four women at their instruments. One symphony, finally complete. Infinite tomorrows stretching ahead like sheet music waiting to be written.", storyZh: "星神咖啡馆举办了最后一次聚会。不是因为咖啡馆要关闭，而是因为这一刻已经足够完整，不需要再重复。四个女人坐在老位置，手中握着各自的乐器。薇薇安妮的笔，写下了无数歌曲的歌词；埃斯黛尔的小提琴，奏响了穿越时空的旋律；伊里斯的琴键，弹出了连接世界的和声；莉莉的鸢尾琴，拨动了三百年的记忆。乐章终于完整了——从开篇的迷茫与失落，到中段的挣扎与寻找，再到此刻的圆满与希望。但这不是结束。无限的明天如同空白的乐谱，在她们面前展开，等待着被书写。新的乐章将会诞生，新的故事将会发生，而她们将永远是这首交响曲的演奏者。"},
  98: { date: "Jan 18, 2159", dateZh: "2159年1月18日", story: "The symphony swells—three hundred years compressed into one transcendent crescendo. Every world that was sacrificed, every friend that was lost, every note that was ever played—all converging in this moment.", storyZh: "乐章达到了高潮。三百年的时光被压缩成一个超凡的渐强，如同千万条河流汇聚成海洋。每个被牺牲的世界都在这个音符中找到了一席之地——那些在战火中化为灰烬的文明，那些在合并中被抹去的时间线；每个失去的朋友都在这个和弦中得到了安息——埃斯黛尔在另一条时间线的微笑，祖父在日记中的低语；每个被演奏过的音符都在这个时刻回响——从里格尔岛的第一声祈祷，到咖啡馆里的最后一次合奏。全部汇聚在这一刻，全部融为一体。这是三百年来所有生命、所有梦想、所有牺牲的结晶，是一首真正属于全宇宙的交响曲。"},
  99: { date: "Jan 19, 2159", dateZh: "2159年1月19日", story: "Not a return to the past, but an arrival in the present. Lily opens her eyes. Vivian is beside her, humming. Iris plays piano. Lisdela tunes violin. 'I'm home,' she whispers. And she is.", storyZh: "不是回到过去——过去已经消逝，无法挽回。而是到达现在，此刻，在这里。莉莉睁开眼睛。薇薇安妮在她身边轻轻哼唱着，旋律简单却温暖；伊里斯在弹钢琴，手指在琴键上飞舞；埃斯黛尔在调整她的小提琴，专注而宁静。这就是家。不是某个具体的地点，不是某段特定的时间，而是这个瞬间——当所爱的人都在身边，当音乐在空中流淌，当过去的所有伤痛都化为了此刻的安宁。'我到家了，'莉莉低语，声音中带着满足与平静。是的，她到家了。不是穿越回失去的世界，而是在这里找到了归属；不是找回过去，而是在当下创造了新的意义。"},
  100: { date: "Jan 20, 2159", dateZh: "2159年1月20日", story: "The future is not a place we return to—it is a home we compose, together, note by note. The symphony plays on, and will always play on. This is Le Foyer du Futur. This is where we belong.", storyZh: "未来不是我们回归的地方——它从来就不是。它不是一个我们能够返回的故土，而是一个我们共同创作的新家。一个音符接着一个音符，一段旋律接着一段旋律，我们所有人一起，书写着属于这个时代的乐章。咖啡馆里的音乐还在继续，永远不会停止。因为只要还有人在演奏，只要还有人愿意倾听，只要还有人相信音乐的力量，这首交响曲就会永远回响下去。这就是《未来的故乡》——不是某个具体的坐标，而是我们共同创造的归属感；不是过去的延续，而是未来的开端。这里是我们属于的地方，是每一个曾经失去家园、却依然相信希望的人永恒的归处。" }
}
// Get story for a stage, returns default if not found
export function getStageStory(stageId) {
  const story = STAGE_STORIES[stageId]
  if (story) return story

  // Default story for stages without specific content
  const chapter = Math.ceil(stageId / 10)
  return {
    date: `Day ${stageId + 60}, 2157`,
    dateZh: `2157年第${stageId + 60}天`,
    story: `The journey continues. New challenges await as Lily ventures deeper into unknown territories. Each battle brings her closer to the truth her grandfather sought.`,
    storyZh: `旅程继续。随着莉莉深入未知领域，新的挑战等待着她。每一次战斗都让她更接近祖父所寻求的真相。`
  }
}
